def role_tasks(role):
 ts=deepcopy([x for x in TASKS if role in x['roles']]);d={x['id']:x for x in ts}
 for t in ts:t['roles']=[role]
 # Read-only and handoff instructions are substantive role-specific rewrites.
 c=d['C01'];c['steps'][1]=('접속 구분에서 관리자를 선택합니다.'if role=='ADMIN'else'접속 구분에서 사용자를 선택합니다. 관리자 구분으로 선택해도 관리자 권한이 생기지 않습니다.')
 c['pre']=f'승인된 {NAMES[role]} 계정과 본인 비밀번호를 준비합니다. 화면의 demo 계정은 교육용 예시입니다.'
 c['steps'][3]=f'왼쪽 아래 역할이 {NAMES[role]}인지 확인합니다. 다르면 업무를 중단하고 관리자에게 역할 확인을 요청합니다.'
 if role!='ADMIN':c['fix']='아이디·접속 구분·비밀번호를 확인합니다. 승인 대기·반려이면 관리자에게 신청 아이디와 메시지를 전달합니다. 비밀번호는 전달하지 않습니다.'
 d['C04']['shot']='current-'+role+'-dashboard'
 c=d['C05']
 if role=='VIEWER':
  c.update(title='첨부자료 조회·열기',pre='조회전용은 고장·정비 첨부를 조회할 수 있지만 추가·삭제할 수 없습니다.',steps=['정확한 접수번호 또는 작업번호의 상세를 엽니다.','첨부자료 목록에서 파일명·자료 구분·등록자·크기·설명을 확인합니다.','열기 아이콘을 누르면 Windows 기본 연결 앱으로 파일이 열립니다. 기본 연결 앱 실행은 이번 실제 검증 범위 밖입니다.','잘못된 파일이나 누락은 업무 번호와 파일명을 적어 등록자 또는 관리자에게 요청합니다.'],fields=[['업무 번호','조회','고장 또는 정비의 번호','확인 대상 번호'],['파일명','조회','현재 첨부된 자료','교육용점검.txt']],result='업무에 연결된 자료의 이름과 의미를 확인합니다. 추가·삭제는 수행하지 않습니다.',next='공유 전 조직의 허용 범위를 확인합니다.',fix='권한·저장 위치·기본 연결 앱 문제는 업무 번호와 파일명을 관리자에게 전달합니다.',warn='추가·삭제 버튼이 보이더라도 변경하지 않습니다. 삭제·복구는 관리자에게 요청합니다.')
 elif role=='USER':
  c['title']='본인 고장 첨부 관리와 정비 첨부 조회';c['steps'][0]='고장관리에서 본인이 접수한 건의 상세를 엽니다. 정비 첨부에는 아래 추가·삭제 절차를 적용하지 않습니다.';c['pre']='본인이 접수한 고장의 첨부만 추가할 수 있습니다. 본인 고장에 연결된 정비 첨부는 조회만 가능하며, 종결·취소된 고장의 첨부 변경은 관리자에게 요청합니다.';c['fix']='본인이 올린 파일도 고장이 종결·취소되면 삭제할 수 없습니다. 다른 등록자가 올린 파일은 관리자에게 삭제 요청합니다. 형식·크기 오류는 지원 파일로 준비하고 다시 선택합니다.'
 elif role=='MAINTAINER':c['pre']='개인 배정·가용 소속팀 조건의 고장, 또는 본인 정비/배정·팀 조건의 연계 고장이 있는 정비 첨부에 접근합니다. 목록에 작업이 보여도 첨부 권한은 별도입니다. 완료·종결·취소 건은 변경할 수 없습니다.'
 elif role=='OPERATOR':c['pre']='고장·정비 첨부를 조회하고 진행 중 업무에 자료를 추가할 수 있습니다. 삭제는 본인이 올린 파일만 가능하며 완료·종결·취소 건은 관리자에게 요청합니다.'
 else:c['pre']='관리자는 고장·정비 첨부를 관리할 수 있습니다. 완료·종결 건도 변경할 수 있으므로 삭제 전에 업무 번호·파일명·보존 필요성을 확인합니다.'
 if 'C06'in d:
  c=d['C06'];c['shot']='current-'+role+'-ai';c['fields'][3:] = []
  c['steps']=['AI 지원에서 제목에 교육용 회선 장애, 내용에 가상 교육실 단말 2대 접속 불가를 입력합니다.','분석 및 유사 고장 조회를 누르고 처리가 끝날 때까지 기다립니다.','분류·우선순위·권장 조치·근거를 실제 증상과 비교합니다.','표시된 Provider·모델·처리 시간·Local Rule fallback·외부 전송 여부를 확인합니다.','유사 고장의 번호와 조치 내용을 현재 조건에 맞는지 검토합니다. 결과만으로 업무 상태를 바꾸지 않습니다.']
  if role!='USER':c['steps']+=['일일 요약 생성과 정비 우선순위 조회를 각각 눌러 참고 결과를 확인합니다. 원본 목록과 날짜·상태를 대조합니다.']
